-- Current-only G1/G9 release. Source authentication is the reviewed Actions
-- reader boundary; this service-only transaction independently proves DB facts.
create schema private_fcf_target_release;
revoke all on schema private_fcf_target_release from public,anon,authenticated,service_role;
create table private_fcf_target_release.club_bindings(competition_id bigint not null references public.competitions,club_id text not null,category_id text not null,team_id bigint not null references public.teams,country_id bigint not null,source_fingerprint text not null,primary key(competition_id,club_id,category_id),unique(competition_id,team_id));
create table private_fcf_target_release.receipts(id bigint generated always as identity primary key,competition_id bigint not null references public.competitions,inventory_key text not null,packet_sha256 text not null,packet_text text not null,rollout_text text not null,rollout_sha256 text not null,source_fingerprint text not null,cleanup_before_sha256 text not null,imported_state_sha256 text not null,stage text not null check(stage in('imported','activated')),activation_result jsonb,created_at timestamptz not null default clock_timestamp(),unique(competition_id,inventory_key));
revoke all on all tables in schema private_fcf_target_release from public,anon,authenticated,service_role;
create function private_fcf_target_release.require(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FCF_TARGET: %',message;end if;end$$;
create function private_fcf_target_release.target_id(slug text)returns bigint language sql immutable as $$select case slug when 'es-ct-segona-g1'then 783::bigint when 'es-ct-tercera-g9'then 797::bigint end$$;
create function private_fcf_target_release.lock_target(cid bigint)returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare catalog jsonb;
begin
 perform private_fcf_target_release.require(current_setting('transaction_isolation')='read committed','READ COMMITTED required');
 perform private_fcf_target_release.require(cid in(783,797),'exact G1/G9 target required');
 lock table countries,competitions,rounds,teams,players,matches,appearances,goals,fantasy_teams,fantasy_roster,fantasy_lineups,fantasy_transfers,fantasy_chips,position_votes,position_votes_deleted,assist_votes,assist_votes_deleted,player_scores,statistika_igralcev,tocke_krogov,uradne_odsotnosti,profil_igralca_plus,anonimizirani_igralci,federations in share row exclusive mode;
 lock table private_historical_statistics.policies,private_historical_statistics.installed_policies,private_historical_statistics.markers,private_historical_statistics.source_club_bindings,private_fcf_target_release.club_bindings,private_fcf_target_release.receipts in share row exclusive mode;
 perform 1 from competitions where id in(783,790,797)order by id for update;
 select coalesce(jsonb_agg(jsonb_build_object('schema',ns.nspname,'table',t.relname,'target',p.relname,'definition',pg_get_constraintdef(c.oid))order by ns.nspname,t.relname,c.conname),'[]')into catalog from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace ns on ns.oid=t.relnamespace join pg_class p on p.oid=c.confrelid where c.contype='f'and c.confrelid in('public.appearances'::regclass,'public.goals'::regclass,'public.player_scores'::regclass,'public.statistika_igralcev'::regclass,'public.tocke_krogov'::regclass);
 perform private_fcf_target_release.require(catalog='[{"schema":"public","table":"assist_votes","target":"goals","definition":"FOREIGN KEY (goal_id) REFERENCES goals(id) ON DELETE CASCADE"}]'::jsonb,'unreviewed individual-row FK dependency');
 perform private_fcf_target_release.require(not exists(select 1 from pg_attribute a join pg_class t on t.oid=a.attrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname in('public','scout')and t.relkind in('r','p')and a.attnum>0 and not a.attisdropped and a.attname in('appearance_id','goal_id')and not(n.nspname='public'and t.relname in('assist_votes','assist_votes_deleted')and a.attname='goal_id')),'unreviewed individual reference column');
end$$;

create function private_fcf_target_release.no_target_users(cid bigint)returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 perform private_fcf_target_release.require(not exists(select 1 from fantasy_teams where competition_id=cid),'target fantasy teams including house teams');
 perform private_fcf_target_release.require(not exists(select 1 from fantasy_roster f join players p on p.id=f.player_id where p.competition_id=cid),'target roster activity');
 perform private_fcf_target_release.require(not exists(select 1 from fantasy_lineups f join rounds r on r.id=f.round_id join players p on p.id=f.player_id where r.competition_id=cid or p.competition_id=cid),'target lineup activity');
 perform private_fcf_target_release.require(not exists(select 1 from fantasy_transfers f join rounds r on r.id=f.round_id where r.competition_id=cid)and not exists(select 1 from fantasy_chips f join rounds r on r.id=f.round_id where r.competition_id=cid),'target transfer/chip activity');
 perform private_fcf_target_release.require(not exists(select 1 from position_votes v join players p on p.id=v.player_id where p.competition_id=cid)and not exists(select 1 from position_votes_deleted v join players p on p.id=v.player_id where p.competition_id=cid),'target position votes');
 perform private_fcf_target_release.require(not exists(select 1 from assist_votes v join goals g on g.id=v.goal_id join matches m on m.id=g.match_id join rounds r on r.id=m.round_id where r.competition_id=cid)and not exists(select 1 from assist_votes_deleted v join goals g on g.id=v.goal_id join matches m on m.id=g.match_id join rounds r on r.id=m.round_id where r.competition_id=cid),'target assist votes');
 perform private_fcf_target_release.require(not exists(select 1 from tocke_krogov t join rounds r on r.id=t.round_id where r.competition_id=cid),'target fantasy score cache activity');
 perform private_fcf_target_release.require(not exists(select 1 from goals g join matches m on m.id=g.match_id join rounds r on r.id=m.round_id where r.competition_id=cid and(g.assist_player_id is not null or g.assist_confirmed_at is not null or g.assist_none_confirmed_at is not null)),'target confirmed assists');
end$$;
create function private_fcf_target_release.markers()returns void language plpgsql security definer set search_path=public,pg_temp as $$declare t record;m jsonb;begin
 for t in select *from(values(783,array['4109388']), (790,array['4116215']), (797,array['4118352','4118358']))x(cid,ids)loop
  m:=public.get_installed_historical_statistics_markers(t.cid);
  perform private_fcf_target_release.require(m->'installed'='true'::jsonb and m->>'firstFantasyPlayedOn'='2026-10-24'and(select array_agg(x->>'sourceMatchId'order by x->>'sourceMatchId')from jsonb_array_elements(m->'markers')x)=t.ids,'complete immutable all-four cleanup required');
 end loop;
end$$;
create function private_fcf_target_release.validate(p_text text,p_sha text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v jsonb;p jsonb;g jsonb;b jsonb;c competitions%rowtype;mp jsonb;policy private_historical_statistics.policies%rowtype;marker jsonb;due timestamptz;
begin
 perform private_fcf_target_release.require(p_sha~'^[a-f0-9]{64}$'and octet_length(p_text)<=8388608 and encode(sha256(convert_to(p_text,'UTF8')),'hex')=p_sha,'exact bounded rollout TEXT/SHA');v:=p_text::jsonb;
 perform private_fcf_target_release.require(v->>'schemaVersion'='1'and v->>'kind'='fcf-current-target-rollout'and v->>'sourceCommit'~'^[a-f0-9]{40}$'and(select array_agg(k order by k)from jsonb_object_keys(v)k)=array['cleanupBinding','execution','identityPlan','inventoryBinding','kind','readiness','schemaVersion','sourceCommit','targetPacketSha256','targetPacketText','targetSlug'],'closed new-inventory rollout schema');
 select *into c from competitions where id=private_fcf_target_release.target_id(v->>'targetSlug');
 perform private_fcf_target_release.require(c.id is not null and c.source='fcf'and c.source_policy='es-fcf-reviewed-history-v1'and c.source_league_code=case c.id when 783 then '4109388-4109627'else '4118349-4118588'end and not c.sezona_koledarska and c.rok_pomak_ur=6 and c.date_only_deadline_policy is null and exists(select 1 from countries where id=c.country_id and code='ES'),'exact current source/policy/calendar tuple');
 perform private_fcf_target_release.require(encode(sha256(convert_to(v->>'targetPacketText','UTF8')),'hex')=v->>'targetPacketSha256','nested packet TEXT/SHA');p:=(v->>'targetPacketText')::jsonb;g:=p->'target';b:=g->'sourceEvidence';
 perform private_fcf_target_release.require(p->>'schemaVersion'='2'and p->>'kind'='fcf-current-target-release'and p->>'targetSlug'=c.slug and p->>'sourceCommit'=v->>'sourceCommit'and(g->>'competitionId')::bigint=c.id and g->>'competitionSlug'=c.slug and g->>'season'='2026/27'and g->>'firstFantasyPlayedOn'='2026-10-24'and b=v->'inventoryBinding'and b->>'kind'='fcf-missing-target-admission'and b->>'targetSlug'=c.slug and b->>'sourceClaimState'='consumed'and b->>'sourceCommit'~'^[a-f0-9]{40}$'and b->>'sourceFingerprintSha256'~'^[a-f0-9]{64}$'and b->>'maximumSourceGETs'='477'and(b->>'actualSourceGETs')::int between 1 and 477 and b->'claimBinding'is not null and b->'consumptionBinding'is not null and b->'inventoryBinding'is not null and b->'auditBinding'is not null and b->'finalReceiptBinding'is not null,'authenticated new captured target identity required; legacy closed');
 perform private_fcf_target_release.require(p->'cleanupBinding'=v->'cleanupBinding'and v#>>'{cleanupBinding,phase}'='applied'and encode(sha256(convert_to(v#>>'{cleanupBinding,beforeImageText}','UTF8')),'hex')=v#>>'{cleanupBinding,beforeSha256}'and v#>>'{cleanupBinding,appliedReceipt,result,removedAppearances}'='126'and v#>>'{cleanupBinding,appliedReceipt,result,removedGoals}'='14'and v#>>'{cleanupBinding,appliedReceipt,result,unavailableMatches}'='4','opaque immutable all-four applied backup/receipt required');
 perform private_fcf_target_release.markers();select *into policy from private_historical_statistics.policies where id=g->>'policyId';
 perform private_fcf_target_release.require(policy.document->>'competitionSlug'=c.slug and policy.policy_sha256=g->>'policySha256','installed target policy/hash required');
 mp:=(v#>>'{identityPlan,mappingText}')::jsonb;
 perform private_fcf_target_release.require(encode(sha256(convert_to(v#>>'{identityPlan,mappingText}','UTF8')),'hex')=v#>>'{identityPlan,mappingSha256}'and mp->>'kind'='fcf-native-target-mapping'and mp->>'targetSlug'=c.slug and mp->>'sourceCommit'=v->>'sourceCommit'and mp->>'sourceFingerprintSha256'=b->>'sourceFingerprintSha256'and jsonb_array_length(mp->'mappings')=16 and jsonb_array_length(mp->'fixtures')=240,'reviewed native mapping text/identity required');
 drop table if exists pg_temp._fcf_clubs;create temporary table pg_temp._fcf_clubs on commit drop as select x->>'nativeClubId'club,x->>'nativeCategoryId'category,(x->>'teamId')::bigint team,x->>'sourceName'name,x->>'canonicalTeamName'canonical_name from jsonb_array_elements(mp->'mappings')x;
 perform private_fcf_target_release.require((select count(distinct(club,category))from pg_temp._fcf_clubs)=16 and(select count(distinct team)from pg_temp._fcf_clubs)=16 and not exists(select 1 from pg_temp._fcf_clubs n left join teams t on t.id=n.team where t.id is null or t.country_id<>c.country_id),'native club/team/country bijection required');
 drop table if exists pg_temp._fcf_expected;create temporary table pg_temp._fcf_expected(id text primary key,f jsonb,mid bigint unique,rid bigint,rn int,home bigint,away bigint)on commit drop;
 insert into pg_temp._fcf_expected select f->>'id',f,(x->>'matchId')::bigint,(x->>'roundId')::bigint,(f->>'round')::int,h.team,a.team from jsonb_array_elements(g->'fixtures')f join lateral(select value x from jsonb_array_elements(mp->'fixtures')where value->>'sourceMatchId'=f->>'id')map on true join pg_temp._fcf_clubs h on h.club=f#>>'{clubs,0,sourceClubId}'and h.category=f#>>'{clubs,0,sourceCategoryId}'join pg_temp._fcf_clubs a on a.club=f#>>'{clubs,1,sourceClubId}'and a.category=f#>>'{clubs,1,sourceCategoryId}';
 perform private_fcf_target_release.require((select count(*)from pg_temp._fcf_expected)=240 and(select count(*)from rounds where competition_id=c.id)=30 and(select count(*)from matches m join rounds r on r.id=m.round_id where r.competition_id=c.id)=240 and(select count(distinct(home,away))from pg_temp._fcf_expected)=240 and not exists(select 1 from pg_temp._fcf_expected e left join matches m on m.id=e.mid left join rounds r on r.id=e.rid where m.id is null or m.round_id<>e.rid or r.competition_id<>c.id or r.season<>'2026/27'or r.number<>e.rn or e.home=e.away or m.home_team_id<>e.home or m.away_team_id<>e.away or(m.zapisnik_id is not null and m.zapisnik_id<>e.id)or(m.imported_at is not null and e.f->>'statisticsStatus'='pending')or e.id!~'^es[1-9][0-9]*$'or substring(e.id from 3)::bigint not between(case c.id when 783 then 4109388 else 4118349 end)and(case c.id when 783 then 4109627 else 4118588 end)),'complete actual native240/30/calendar/import preservation required');
 perform private_fcf_target_release.require(not exists(select n from generate_series(1,30)n left join pg_temp._fcf_expected e on e.rn=n group by n having count(e.id)<>8 or count(distinct e.home)filter(where e.home is not null)>8 or count(distinct e.away)filter(where e.away is not null)>8)and not exists(select rn from(select rn,home team from pg_temp._fcf_expected union all select rn,away from pg_temp._fcf_expected)x group by rn having count(distinct team)<>16),'every club once per actual source round');
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where e.f->>'statisticsStatus'not in('available','pending','unavailable_historical')or e.f->>'statisticsStatus'is null or e.f->>'statisticsStatus'<>'unavailable_historical'and(e.f#>>'{source,capturedUTC}'is null or(e.f#>>'{source,capturedUTC}')::timestamptz>clock_timestamp()or(e.f#>>'{source,capturedUTC}')::timestamptz<clock_timestamp()-interval '24 hours')),'strict current source clocks/status required');
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where e.f->>'statisticsStatus'='pending'and clock_timestamp()-((e.f->>'date')::date::timestamp at time zone'UTC')between interval'-1 day'and interval'14 days'and(e.f#>>'{source,capturedUTC}')::timestamptz<clock_timestamp()-interval'1 hour'),'pending source provider one-hour freshness required');
 perform private_fcf_target_release.require((select array_agg(substring(id from 3)order by id)from pg_temp._fcf_expected where f->>'statisticsStatus'='unavailable_historical')=(select array_agg(x->>'sourceMatchId'order by x->>'sourceMatchId')from jsonb_array_elements(policy.document->'entries')x),'exact target historical exceptions only');
 for marker in select value from jsonb_array_elements(policy.document->'entries')loop
  perform private_fcf_target_release.require(exists(select 1 from pg_temp._fcf_expected where id='es'||(marker->>'sourceMatchId')and f->'appearances'='null'::jsonb and f->'goals'='null'::jsonb and f#>>'{source,rawSha256}'=marker->>'rawSha256'and f->>'statisticsReason'=marker->>'reasonCode'and f->'sourceFixture'=(marker-array['rawSha256','reasonCode'])||jsonb_build_object('season','2026/27')),'immutable unavailable header/hash/null facts required');
 end loop;
 drop table if exists pg_temp._fcf_apps;create temporary table pg_temp._fcf_apps on commit drop as select e.id,e.mid,e.rid,e.rn,e.f->>'date' as source_day,(x->>'regSt')::bigint reg,case x->>'ekipaIdx'when '0'then e.home when '1'then e.away end team,x from pg_temp._fcf_expected e cross join lateral jsonb_array_elements(case when f->>'statisticsStatus'='available'then f->'appearances'else '[]'::jsonb end)x;
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_apps where reg is null or reg<1 or team is null or x->>'ime'is null or jsonb_typeof(x->'zacetnik')is distinct from'boolean'or jsonb_typeof(x->'vratar')is distinct from'boolean'or jsonb_typeof(x->'cleanSheet')is distinct from'boolean'or exists(select 1 from unnest(array['goli','avtogoli','goliIzEnajstmetrovke','zgreseneEnajstmetrovke','rumeni','rdeci','prejetiGoli'])field where jsonb_typeof(x->field)is distinct from'number'or(x->>field)::int<0)or(x->>'minute')::int<0 or(x->>'minutaOd')::int<0 or(x->>'minutaDo')::int>90 or(x->>'minute')::int<>(x->>'minutaDo')::int-(x->>'minutaOd')::int)and not exists(select id,reg from pg_temp._fcf_apps group by id,reg having count(*)<>1),'native appearance identity/intervals');
 perform private_fcf_target_release.require(not exists(select id,team from pg_temp._fcf_apps group by id,team having count(*)filter(where(x->>'zacetnik')::boolean)<>11 or count(*)filter(where(x->>'zacetnik')::boolean and(x->>'vratar')::boolean)<>1)and not exists(select 1 from(select id,team,(x->>'minutaOd')::int a,(x->>'minutaDo')::int b,lag((x->>'minutaDo')::int,1,0)over(partition by id,team order by(x->>'minutaOd')::int,(x->>'minutaDo')::int)previous from pg_temp._fcf_apps where(x->>'vratar')::boolean and(x->>'minute')::int>0)k where a<>previous)and not exists(select id,team from pg_temp._fcf_apps where(x->>'vratar')::boolean and(x->>'minute')::int>0 group by id,team having max((x->>'minutaDo')::int)<>90),'explicit XI and continuous exactly-one source GK0-90');
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where f->>'statisticsStatus'='available'and(rn>=6 or coalesce(f#>'{report,opozorila}','null')<>'[]'::jsonb or(select count(*)from pg_temp._fcf_apps a where a.id=e.id)<22)),'normal complete current reports only; no source-role repair');
 drop table if exists pg_temp._fcf_goals;create temporary table pg_temp._fcf_goals on commit drop as select e.id,e.mid,(ge.goal->>'regSt')::bigint reg,case ge.goal->>'ekipaIdx'when '0'then e.home when '1'then e.away end team,ge.goal as g from pg_temp._fcf_expected e cross join lateral jsonb_array_elements(case when f->>'statisticsStatus'='available'then f->'goals'else '[]'::jsonb end)ge(goal);
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_goals g where g.reg is null or not exists(select 1 from pg_temp._fcf_apps a where a.id=g.id and a.reg=g.reg and a.team=g.team and(g.g->>'minuta')::int between(a.x->>'minutaOd')::int and(a.x->>'minutaDo')::int))and not exists(select 1 from pg_temp._fcf_expected e where f->>'statisticsStatus'='available'and((select count(*)from pg_temp._fcf_goals g where g.id=e.id and case when(g.g->>'avtogol')::boolean then g.team=e.away else g.team=e.home end)<>(f->>'homeGoals')::int or(select count(*)from pg_temp._fcf_goals g where g.id=e.id and case when(g.g->>'avtogol')::boolean then g.team=e.home else g.team=e.away end)<>(f->>'awayGoals')::int)),'native goal actors/score accounting');
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_apps a where(a.x->>'goli')::int<>(select count(*)from pg_temp._fcf_goals ge where ge.id=a.id and ge.reg=a.reg and not(ge.g->>'avtogol')::boolean)or(a.x->>'avtogoli')::int<>(select count(*)from pg_temp._fcf_goals ge where ge.id=a.id and ge.reg=a.reg and(ge.g->>'avtogol')::boolean)or(a.x->>'goliIzEnajstmetrovke')::int<>(select count(*)from pg_temp._fcf_goals ge where ge.id=a.id and ge.reg=a.reg and(ge.g->>'enajstmetrovka')::boolean and not(ge.g->>'avtogol')::boolean)),'native per-player goal event counters differ');
 perform private_fcf_target_release.require((select count(*)from pg_temp._fcf_expected where rn=6)=8 and not exists(select 1 from pg_temp._fcf_expected where rn=6 and(f->>'statisticsStatus'<>'pending'or f->>'time'is null or(f->>'date')::date<'2026-10-24'))and(select min((f->>'date')::date)from pg_temp._fcf_expected where rn=6)='2026-10-24','exact pending genuine future R6');
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where e.rn=6 and(e.f->>'time'!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'or ((((e.f->>'date')::date+(e.f->>'time')::time)at time zone'Europe/Madrid')at time zone'Europe/Madrid')is distinct from((e.f->>'date')::date+(e.f->>'time')::time)or (((((e.f->>'date')::date+(e.f->>'time')::time)at time zone'Europe/Madrid')-interval'1 hour')at time zone'Europe/Madrid')=((e.f->>'date')::date+(e.f->>'time')::time)or (((((e.f->>'date')::date+(e.f->>'time')::time)at time zone'Europe/Madrid')+interval'1 hour')at time zone'Europe/Madrid')=((e.f->>'date')::date+(e.f->>'time')::time))),'unambiguous official R6 local kickoff required');
 select min(((e.f->>'date')::date+(e.f->>'time')::time)at time zone'Europe/Madrid')-interval '6 hours'into due from pg_temp._fcf_expected e where e.rn=6;
 perform private_fcf_target_release.require(due>clock_timestamp(),'source R6 deadline genuinely future');return v;
end$$;

create function private_fcf_target_release.privacy(cid bigint)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare country bigint;begin
 select country_id into country from competitions where id=cid;
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_apps a join anonimizirani_igralci k on k.kljuc in(public.anonimizacijski_kljuc(country||'|reg|'||a.reg),public.anonimizacijski_kljuc(country||'|'||(a.x->>'ime')))join players p on p.id=k.player_id join competitions c on c.id=p.competition_id where c.country_id=country and(p.competition_id=cid or p.anonimiziran_razlog='ugovor')),'protected privacy/native identity; permitted restoration is a separate normal route');
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_apps a join players p on p.competition_id=cid and(p.reg_st=a.reg or(p.reg_st is null and p.full_name=a.x->>'ime'))where p.reg_st is null or p.anonimiziran_at is not null or p.anonimiziran_razlog is not null),'ambiguous or protected native player identity');
 perform private_fcf_target_release.require(not exists(select reg from pg_temp._fcf_apps where(source_day::date,reg)in(select max(source_day::date),reg from pg_temp._fcf_apps group by reg)group by reg having count(distinct team)>1),'same-date conflicting current native clubs');
end$$;
create function private_fcf_target_release.compare_canonical(cid bigint)returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_expected e join matches m on m.id=e.mid where m.played_on is distinct from(e.f->>'date')::date or m.source_url is distinct from e.f#>>'{source,sourceUrl}'or m.zapisnik_id is distinct from e.id or m.kontumacija or m.vir_brez_izida or m.source_phase is not null or m.source_round is distinct from e.rn or(e.f->>'statisticsStatus'='available'and(m.imported_at is null or m.statistics_status<>'available'or m.statistics_reason is not null or m.home_goals is distinct from(e.f->>'homeGoals')::int or m.away_goals is distinct from(e.f->>'awayGoals')::int or m.import_warnings<>array[]::text[]))or(e.f->>'statisticsStatus'='pending'and(m.imported_at is not null or m.home_goals<>0 or m.away_goals<>0))),'persisted native fixture/clock/status/result mismatch');
 perform private_fcf_target_release.require(not exists(with expected as(select mid,reg,team,(x->>'st')::int shirt_number,(x->>'zacetnik')::boolean started,(x->>'minutaOd')::int minute_on,(x->>'minutaDo')::int minute_off,(x->>'minute')::int minutes_played,(x->>'goli')::int goals,(x->>'avtogoli')::int own_goals,(x->>'goliIzEnajstmetrovke')::int penalties_scored,(x->>'zgreseneEnajstmetrovke')::int penalties_missed,(x->>'rumeni')::int yellow_cards,(x->>'rdeci')::int red_cards,(x->>'prejetiGoli')::int goals_conceded,(x->>'cleanSheet')::boolean clean_sheet,(x->>'vratar')::boolean is_goalkeeper from pg_temp._fcf_apps),actual as(select a.match_id,p.reg_st,a.team_id,a.shirt_number,a.started,a.minute_on,a.minute_off,a.minutes_played,a.goals,a.own_goals,a.penalties_scored,a.penalties_missed,a.yellow_cards,a.red_cards,a.goals_conceded,a.clean_sheet,a.is_goalkeeper from appearances a join players p on p.id=a.player_id where a.match_id in(select mid from pg_temp._fcf_expected)) (select *from expected except all select *from actual)union all(select *from actual except all select *from expected)),'complete native appearance multiset mismatch');
 perform private_fcf_target_release.require(not exists(with expected as(select mid,reg,team,(g->>'minuta')::int as event_minute,(g->>'avtogol')::boolean own_goal,(g->>'enajstmetrovka')::boolean penalty,(g#>>'{rezultat,0}')::int score_home,(g#>>'{rezultat,1}')::int score_away from pg_temp._fcf_goals),actual as(select g.match_id,p.reg_st,g.team_id,g.minute,g.is_own_goal,g.is_penalty,g.score_home,g.score_away from goals g join players p on p.id=g.scorer_id where g.match_id in(select mid from pg_temp._fcf_expected)) (select *from expected except all select *from actual)union all(select *from actual except all select *from expected)),'complete native goal multiset mismatch');
 perform private_fcf_target_release.require(not exists(select 1 from appearances a join players p on p.id=a.player_id where a.match_id in(select mid from pg_temp._fcf_expected)and p.competition_id<>cid)and not exists(select 1 from players p join appearances a on a.player_id=p.id join matches m on m.id=a.match_id join rounds r on r.id=m.round_id where p.competition_id=cid and r.competition_id<>cid),'cross-target native player reference');
 perform private_fcf_target_release.require(not exists(with expected as(select ap.player_id,ap.round_id,sum(ap.points)points from appearance_points ap where ap.round_id in(select rid from pg_temp._fcf_expected)group by ap.player_id,ap.round_id),actual as(select player_id,round_id,points from player_scores where round_id in(select rid from pg_temp._fcf_expected))(select *from expected except all select *from actual)union all(select *from actual except all select *from expected)),'derived player_scores differ');
 perform private_fcf_target_release.require(not exists(with expected as(select to_jsonb(s)||jsonb_build_object('last_round',coalesce((select ps.points from player_scores ps join rounds r on r.id=ps.round_id where ps.player_id=s.player_id and r.season=s.season order by r.number desc limit 1),0),'form',coalesce((select sum(z.points)from(select ps.points from player_scores ps join rounds r on r.id=ps.round_id where ps.player_id=s.player_id and r.season=s.season order by r.number desc limit 3)z),0))x from player_season_stats_izracun s where competition_id=cid),actual as(select to_jsonb(s)x from statistika_igralcev s where competition_id=cid)(select *from expected except all select *from actual)union all(select *from actual except all select *from expected)),'derived current statistics differ');
end$$;

create function public.import_fcf_current_target(p_rollout_text text,p_sha256 text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v jsonb;cid bigint;c competitions%rowtype;rec private_fcf_target_release.receipts%rowtype;k text;f record;x record;current_player players%rowtype;pid bigint;apps jsonb;gs jsonb;due timestamptz;rid bigint;result jsonb;
begin
 cid:=private_fcf_target_release.target_id(p_rollout_text::jsonb->>'targetSlug');perform private_fcf_target_release.lock_target(cid);v:=private_fcf_target_release.validate(p_rollout_text,p_sha256);select *into c from competitions where id=cid;
 k:=encode(sha256(convert_to((v->'inventoryBinding')::text,'UTF8')),'hex');select *into rec from private_fcf_target_release.receipts where competition_id=cid and inventory_key=k;
 if rec.id is not null then
  perform private_fcf_target_release.require(rec.packet_sha256=v->>'targetPacketSha256','different already accepted target packet');perform private_fcf_target_release.compare_canonical(cid);
  return jsonb_build_object('stage',rec.stage,'targetSlug',c.slug,'receiptId',rec.id::text,'noOp',true,'targetPacketSha256',rec.packet_sha256);
 end if;
 perform private_fcf_target_release.require(not c.active and v->'readiness'='null'::jsonb and not exists(select 1 from private_fcf_target_release.receipts where competition_id=cid),'inactive new target import only');perform private_fcf_target_release.no_target_users(cid);perform private_fcf_target_release.privacy(cid);
 perform private_fcf_target_release.require(not exists(select 1 from pg_temp._fcf_clubs n join private_fcf_target_release.club_bindings b on b.competition_id=cid and b.club_id=n.club and b.category_id=n.category where b.team_id<>n.team or b.country_id<>c.country_id),'immutable private native binding conflict');
 insert into private_fcf_target_release.club_bindings select cid,n.club,n.category,n.team,c.country_id,v#>>'{inventoryBinding,sourceFingerprintSha256}'from pg_temp._fcf_clubs n on conflict do nothing;
 for x in select distinct on(aa.reg)aa.reg,aa.team,aa.x from pg_temp._fcf_apps aa order by aa.reg,aa.source_day::date desc,aa.id desc loop
  select *into current_player from players where competition_id=cid and reg_st=x.reg;
  if current_player.id is null then
   insert into players(competition_id,team_id,reg_st,full_name,first_name,last_name,position,position_source)values(cid,x.team,x.reg,x.x->>'ime',regexp_replace(x.x->>'ime','^\S+\s*',''),split_part(x.x->>'ime',' ',1),case when exists(select 1 from pg_temp._fcf_apps aa where aa.reg=x.reg and(aa.x->>'vratar')::boolean)then 'GK'end,case when exists(select 1 from pg_temp._fcf_apps aa where aa.reg=x.reg and(aa.x->>'vratar')::boolean)then 'zapisnik'else 'neznano'end);
  else
   update players set team_id=x.team,shirt_number=(x.x->>'st')::int,active=case when odsel_at is null and izstopil_at is null then true else active end,position=case when position_source is distinct from 'admin'and(position is null or position_source in('neznano','ugibanje'))and exists(select 1 from pg_temp._fcf_apps aa where aa.reg=x.reg and(aa.x->>'vratar')::boolean)then 'GK'else position end,position_source=case when position_source is distinct from 'admin'and(position is null or position_source in('neznano','ugibanje'))and exists(select 1 from pg_temp._fcf_apps aa where aa.reg=x.reg and(aa.x->>'vratar')::boolean)then 'zapisnik'else position_source end where id=current_player.id;
  end if;
 end loop;
 update players set active=false where competition_id=cid and team_id not in(select team from pg_temp._fcf_clubs);
 for f in select *from pg_temp._fcf_expected order by id loop
  if f.f->>'statisticsStatus'='unavailable_historical'then continue;end if;
  update matches set played_on=(f.f->>'date')::date,home_goals=coalesce((f.f->>'homeGoals')::int,0),away_goals=coalesce((f.f->>'awayGoals')::int,0),zapisnik_id=f.id,source_url=f.f#>>'{source,sourceUrl}',source_round=f.rn,source_phase=null,imported_at=case when f.f->>'statisticsStatus'='available'then clock_timestamp()end,import_warnings=array[]::text[],statistics_status='available',statistics_reason=null where id=f.mid;
  select coalesce(jsonb_agg(jsonb_build_object('player_id',p.id,'team_id',a.team,'shirt_number',a.x->'st','started',a.x->'zacetnik','minute_on',a.x->'minutaOd','minute_off',a.x->'minutaDo','minutes_played',a.x->'minute','goals',a.x->'goli','own_goals',a.x->'avtogoli','penalties_scored',a.x->'goliIzEnajstmetrovke','penalties_missed',a.x->'zgreseneEnajstmetrovke','yellow_cards',a.x->'rumeni','red_cards',a.x->'rdeci','goals_conceded',a.x->'prejetiGoli','clean_sheet',a.x->'cleanSheet','is_goalkeeper',a.x->'vratar')),'[]')into apps from pg_temp._fcf_apps a join players p on p.competition_id=cid and p.reg_st=a.reg where a.id=f.id;
  select coalesce(jsonb_agg(jsonb_build_object('scorer_id',p.id,'team_id',g.team,'minute',g.g->'minuta','is_own_goal',g.g->'avtogol','is_penalty',g.g->'enajstmetrovka','score_home',g.g#>'{rezultat,0}','score_away',g.g#>'{rezultat,1}')),'[]')into gs from pg_temp._fcf_goals g join players p on p.competition_id=cid and p.reg_st=g.reg where g.id=f.id;
  perform public.zamenjaj_nastope_tekme(f.mid,apps,gs);
 end loop;
 select min(((e.f->>'date')::date+(e.f->>'time')::time)at time zone'Europe/Madrid')-interval '6 hours'into due from pg_temp._fcf_expected e where e.rn=6;
 select id into rid from rounds where competition_id=cid and season='2026/27'and number=6 and lineups_locked_at is null and deadline_at>clock_timestamp();perform private_fcf_target_release.require(rid is not null,'never reopen a locked/expired R6');update rounds set played_on='2026-10-24',deadline_at=due where id=rid;update competitions set prvi_fantasy_krog=6 where id=cid;
 for rid in select id from rounds where competition_id=cid loop perform public.recompute_round_scores(rid);end loop;perform public.osvezi_statistiko_igralcev(array(select id from players where competition_id=cid));
 perform private_fcf_target_release.compare_canonical(cid);
 insert into private_fcf_target_release.receipts(competition_id,inventory_key,packet_sha256,packet_text,rollout_text,rollout_sha256,source_fingerprint,cleanup_before_sha256,imported_state_sha256,stage)values(cid,k,v->>'targetPacketSha256',v->>'targetPacketText',p_rollout_text,p_sha256,v#>>'{inventoryBinding,sourceFingerprintSha256}',v#>>'{cleanupBinding,beforeSha256}',private_historical_statistics.state_sha256(cid),'imported')returning *into rec;
 return jsonb_build_object('stage','imported','targetSlug',c.slug,'receiptId',rec.id::text,'targetPacketSha256',rec.packet_sha256,'normalReports',(select count(*)from pg_temp._fcf_expected e where e.f->>'statisticsStatus'='available'),'fixtures',240,'nativeClubs',16);
end$$;

create function private_fcf_target_release.pricing_snapshot(cid bigint)returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select jsonb_build_object('stateSha256',private_historical_statistics.state_sha256(cid),'players',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'competition_id',p.competition_id,'team_id',p.team_id,'reg_st',p.reg_st,'active',p.active,'position',p.position,'position_source',p.position_source,'value',p.value,'value_start',p.value_start,'value_locked',p.value_locked,'nzs_top_league',p.nzs_top_league,'nzs_top_league_minutes',p.nzs_top_league_minutes)order by p.id),'[]')from players p where competition_id=cid),'statistics',(select coalesce(jsonb_agg(to_jsonb(s)order by player_id,season),'[]')from player_season_stats s where competition_id=cid),'priorCompetitions',(select coalesce(jsonb_agg(to_jsonb(c)order by c.id),'[]')from competitions c where country_id=(select country_id from competitions where id=cid)),'priorFederations',(select coalesce(jsonb_agg(to_jsonb(f)order by f.id),'[]')from federations f where country_id=(select country_id from competitions where id=cid)),'priorPlayers',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'competition_id',p.competition_id,'reg_st',p.reg_st,'active',p.active,'position',p.position,'value',p.value)order by p.id),'[]')from players p join competitions c on c.id=p.competition_id where c.country_id=(select country_id from competitions where id=cid)and c.source='fcf'and c.id<>cid and p.reg_st in(select reg_st from players where competition_id=cid)and p.anonimiziran_at is null),'priorStatistics',(select coalesce(jsonb_agg(to_jsonb(s)order by s.player_id,s.season),'[]')from player_season_stats s join players p on p.id=s.player_id join competitions c on c.id=p.competition_id where c.country_id=(select country_id from competitions where id=cid)and c.source='fcf'and c.id<>cid and p.reg_st in(select reg_st from players where competition_id=cid)and p.anonimiziran_at is null));
$$;
create function public.get_fcf_target_pricing_snapshot(p_slug text)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare cid bigint;s text;begin
 cid:=private_fcf_target_release.target_id(p_slug);perform private_fcf_target_release.require(cid is not null and current_setting('transaction_read_only')='on','explicit readonly transaction required');s:=private_fcf_target_release.pricing_snapshot(cid)::text;
 return jsonb_build_object('snapshotText',s,'snapshotSha256',encode(sha256(convert_to(s,'UTF8')),'hex'));
end$$;
create function public.get_fcf_current_target_inventory(p_slug text,p_privacy_keys text[])returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare cid bigint;c competitions%rowtype;stamp timestamptz:=clock_timestamp();result jsonb;begin
 cid:=private_fcf_target_release.target_id(p_slug);select *into c from competitions where id=cid;
 perform private_fcf_target_release.require(cid is not null and current_setting('transaction_read_only')='on'and c.source='fcf'and exists(select 1 from countries where id=c.country_id and code='ES')and p_privacy_keys is not null and cardinality(p_privacy_keys)<=20000 and not exists(select 1 from unnest(p_privacy_keys)k where k!~'^[a-f0-9]{64}$'),'closed explicit readonly native/privacy inventory required');
 select jsonb_build_object('capturedUTC',stamp,'method','explicitBEGIN_READ_ONLY_ROLLBACK','groups',(select jsonb_agg(jsonb_build_object('id',co.id,'slug',co.slug,'country_id',co.country_id,'active',co.active,'source',co.source,'sourceLeagueCode',co.source_league_code,'sezona_koledarska',co.sezona_koledarska,'source_policy',co.source_policy,'nativeImportedIDs',coalesce((select jsonb_agg(substring(m.zapisnik_id from 3)order by m.zapisnik_id)from matches m join rounds r on r.id=m.round_id where r.competition_id=co.id and m.imported_at is not null and m.zapisnik_id is not null),'[]')))from competitions co where co.id in(783,790,797)),'teams',(select jsonb_agg(to_jsonb(t)||jsonb_build_object('competition_id',cid)order by t.id)from teams t where t.id in(select m.home_team_id from matches m join rounds r on r.id=m.round_id where r.competition_id=cid union select m.away_team_id from matches m join rounds r on r.id=m.round_id where r.competition_id=cid)),'rounds',(select jsonb_agg(to_jsonb(r)order by number)from rounds r where competition_id=cid),'matches',(select jsonb_agg(to_jsonb(m)order by m.id)from matches m join rounds r on r.id=m.round_id where r.competition_id=cid),'players',(select coalesce(jsonb_agg(to_jsonb(p)order by id),'[]')from players p where competition_id=cid),'installedMarkers',(select jsonb_agg(public.get_installed_historical_statistics_markers(co.id)order by co.id)from competitions co where co.id in(783,790,797)),'existingExceptionBindings',(select jsonb_agg(to_jsonb(b)order by source_club_id,source_category_id)from private_historical_statistics.source_club_bindings b where provider='fcf'),'identityPrivacy',jsonb_build_object('schemaVersion',1,'kind','fcf-native-privacy-projection','countryCode','ES','countryId',c.country_id,'targetCompetitionId',cid,'method','explicitBEGIN_READ_ONLY_ROLLBACK','capturedUTC',stamp,'complete',true,'checkedKeys',to_jsonb(p_privacy_keys),'matches',(select coalesce(jsonb_agg(jsonb_build_object('player_id',p.id,'competition_id',p.competition_id,'country_id',co.country_id,'kljuc',k.kljuc,'anonimiziran_at',p.anonimiziran_at,'anonimiziran_razlog',p.anonimiziran_razlog)order by p.id,k.kljuc),'[]')from anonimizirani_igralci k join players p on p.id=k.player_id join competitions co on co.id=p.competition_id where co.country_id=c.country_id and k.kljuc=any(p_privacy_keys)and p.anonimiziran_at is not null)))into result;
 return result;
end$$;
create function public.check_fcf_current_target(p_rollout_text text,p_sha256 text,p_activate boolean default false)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare cid bigint;v jsonb;c competitions%rowtype;rec private_fcf_target_release.receipts%rowtype;prices jsonb;cost numeric;deadline timestamptz;official timestamptz;locked timestamptz;result jsonb;snapshot text;k text;
begin
 cid:=private_fcf_target_release.target_id(p_rollout_text::jsonb->>'targetSlug');perform private_fcf_target_release.lock_target(cid);v:=private_fcf_target_release.validate(p_rollout_text,p_sha256);select *into c from competitions where id=cid;
 k:=encode(sha256(convert_to((v->'inventoryBinding')::text,'UTF8')),'hex');select *into rec from private_fcf_target_release.receipts where competition_id=cid and inventory_key=k;
 perform private_fcf_target_release.require(rec.id is not null and rec.packet_sha256=v->>'targetPacketSha256'and rec.cleanup_before_sha256=v#>>'{cleanupBinding,beforeSha256}','matching committed native import receipt required');
 if rec.stage='activated'then perform private_fcf_target_release.require(c.active,'activation receipt/state drift');return rec.activation_result||jsonb_build_object('noOp',true);end if;
 perform private_fcf_target_release.require(not c.active and c.prvi_fantasy_krog=6,'selected target remains inactive/current R6');perform private_fcf_target_release.no_target_users(cid);perform private_fcf_target_release.privacy(cid);perform private_fcf_target_release.compare_canonical(cid);
 perform private_fcf_target_release.require((select count(*)from private_fcf_target_release.club_bindings where competition_id=cid)=16 and not exists(select 1 from pg_temp._fcf_clubs n left join private_fcf_target_release.club_bindings b on b.competition_id=cid and b.club_id=n.club and b.category_id=n.category and b.team_id=n.team and b.country_id=c.country_id where b.team_id is null),'full installed native club binding equality');
 snapshot:=private_fcf_target_release.pricing_snapshot(cid)::text;
 perform private_fcf_target_release.require(jsonb_typeof(v->'readiness')='object'and v#>>'{readiness,modelSha256}'~'^[a-f0-9]{64}$'and v#>>'{readiness,pricingSnapshotText}'=snapshot and v#>>'{readiness,pricingSnapshotSha256}'=encode(sha256(convert_to(snapshot,'UTF8')),'hex'),'full actual pricing dependency snapshot differs');
 perform private_fcf_target_release.require(not exists(with expected as(select(x->>'id')::bigint id,(x->>'value')::numeric value,(x->>'value_start')::numeric value_start,x->>'position'position,x->>'position_source'position_source from jsonb_array_elements(v#>'{readiness,priceVector}')x),actual as(select id,value,value_start,position,position_source from players where competition_id=cid)(select *from expected except all select *from actual)union all(select *from actual except all select *from expected)),'recomputed full price/provenance vector mismatch');
 perform private_fcf_target_release.require(not exists(select 1 from players p where p.competition_id=cid and p.active and p.team_id not in(select team from pg_temp._fcf_clubs))and not exists(select 1 from pg_temp._fcf_apps a join players p on p.competition_id=cid and p.reg_st=a.reg where(a.x->>'zacetnik')::boolean and(a.x->>'vratar')::boolean and p.active and p.position is distinct from 'GK')and not exists(select 1 from pg_temp._fcf_clubs n where not exists(select 1 from pg_temp._fcf_apps a join players p on p.competition_id=cid and p.reg_st=a.reg where a.team=n.team and p.team_id=n.team and p.active and p.position='GK'and(a.x->>'zacetnik')::boolean and(a.x->>'vratar')::boolean)),'current selectable clubs/official source keepers');
 prices:=public.stanje_lige(cid);cost:=public.najcenejsi_kader(prices->'igralci');perform private_fcf_target_release.require((prices->>'klubov')::int=16 and cost is not null and cost<=100 and(prices->>'najvisja_cena')::numeric>=8 and coalesce((prices->>'privzetih')::numeric/nullif((prices->>'aktivnih')::numeric,0),1)<=0.7 and(prices->>'golov_brez_nastopa')::int=0,'actual varied prices and affordable legal15 required');
 perform private_fcf_target_release.require(jsonb_array_length(v#>'{readiness,squad}')=15 and(select count(distinct(x->>'id')::bigint)from jsonb_array_elements(v#>'{readiness,squad}')x)=15 and not exists(select 1 from jsonb_array_elements(v#>'{readiness,squad}')x where not exists(select 1 from jsonb_array_elements(prices->'igralci')p where p->'id'=x->'id'))and(select sum((p->>'value')::numeric)from jsonb_array_elements(prices->'igralci')p where(p->>'id')::bigint in(select(x->>'id')::bigint from jsonb_array_elements(v#>'{readiness,squad}')x))<=100,'actual unique affordable witness required');
 perform private_fcf_target_release.require(not exists(select p->>'team_id'from jsonb_array_elements(prices->'igralci')p where(p->>'id')::bigint in(select(x->>'id')::bigint from jsonb_array_elements(v#>'{readiness,squad}')x)group by p->>'team_id'having count(*)>3)and not exists(select q.position from(values('GK',2),('DEF',5),('MID',5),('FWD',3))q(position,n)where(select count(*)from jsonb_array_elements(prices->'igralci')p where p->>'position'=q.position and(p->>'id')::bigint in(select(x->>'id')::bigint from jsonb_array_elements(v#>'{readiness,squad}')x))<>q.n),'legal15 actual position quotas/club limit');
 select deadline_at,lineups_locked_at into deadline,locked from rounds where competition_id=cid and season='2026/27'and number=6;select min(((f->>'date')::date+(f->>'time')::time)at time zone'Europe/Madrid')-interval '6 hours'into official from pg_temp._fcf_expected where rn=6;
 perform private_fcf_target_release.require(deadline=official and deadline>clock_timestamp()and locked is null,'future unlocked official R6 deadline required');
 result:=jsonb_build_object('stage',case when p_activate then 'activated'else 'checked'end,'targetSlug',c.slug,'receiptId',rec.id::text,'targetPacketSha256',rec.packet_sha256,'sourceFingerprintSha256',rec.source_fingerprint,'fixtures',240,'nativeClubs',16,'cheapestLegal15',cost,'firstFantasyRound',6,'deadlineAt',deadline,'active',p_activate);
 if p_activate then
  perform private_historical_statistics.authorize_release(cid,((v->>'targetPacketText')::jsonb)#>>'{target,policyId}',((v->>'targetPacketText')::jsonb)#>>'{target,policySha256}',v->>'targetPacketSha256');update competitions set active=true where id=cid and not active;
  perform private_fcf_target_release.require(found and exists(select 1 from competitions c2 join rounds r on r.competition_id=c2.id and r.number=6 and r.season='2026/27'where c2.id=cid and c2.active and c2.prvi_fantasy_krog=6 and r.deadline_at=deadline and r.deadline_at>clock_timestamp()and r.lineups_locked_at is null),'same-TX active future deadline readback');
  update private_fcf_target_release.receipts set stage='activated',activation_result=result where id=rec.id;
 end if;return result;
end$$;
create function public.read_fcf_current_target_receipt(p_slug text)returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select coalesce((select (to_jsonb(r)-array['packet_text','rollout_text','rollout_sha256'])||jsonb_build_object('rolloutText',r.rollout_text,'rolloutSha256',r.rollout_sha256,'currentActive',c.active,'currentStateSha256',private_historical_statistics.state_sha256(c.id),'canonicalVerified',false)from private_fcf_target_release.receipts r join competitions c on c.id=r.competition_id where r.competition_id=private_fcf_target_release.target_id(p_slug)),'null')$$;
-- The existing180200 operation still performs the exact atomic cleanup. This
-- receipt closes ambiguous-commit/failed-retention recovery without reapplying it.
create table private_fcf_target_release.cleanup_receipt(singleton boolean primary key default true check(singleton),main_commit text not null,policy_hashes jsonb not null,before_sha256 text not null,before_image_text text not null,result jsonb not null);
revoke all on private_fcf_target_release.cleanup_receipt from public,anon,authenticated,service_role;
create function public.apply_fcf_current_target_cleanup(p_main_sha text,p_policy_hashes jsonb,p_before_sha text,p_before_image_text text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare r private_fcf_target_release.cleanup_receipt%rowtype;result jsonb;begin
 perform private_fcf_target_release.lock_target(783);lock table private_fcf_target_release.cleanup_receipt in share row exclusive mode;select *into r from private_fcf_target_release.cleanup_receipt;
 if r.singleton then
  perform private_fcf_target_release.require(r.main_commit=p_main_sha and r.policy_hashes=p_policy_hashes and r.before_sha256=p_before_sha and r.before_image_text=p_before_image_text,'different already committed cleanup');perform private_fcf_target_release.markers();return r.result;
 end if;
 result:=public.apply_fcf_historical_cleanup(p_main_sha,p_policy_hashes,p_before_sha,p_before_image_text);perform private_fcf_target_release.markers();
 insert into private_fcf_target_release.cleanup_receipt values(true,p_main_sha,p_policy_hashes,p_before_sha,p_before_image_text,result);return result;
end$$;
revoke all on function public.apply_fcf_current_target_cleanup(text,jsonb,text,text)from public,anon,authenticated;
grant execute on function public.apply_fcf_current_target_cleanup(text,jsonb,text,text)to service_role;
revoke all on all functions in schema private_fcf_target_release from public,anon,authenticated,service_role;
revoke all on function public.import_fcf_current_target(text,text),public.check_fcf_current_target(text,text,boolean),public.get_fcf_current_target_inventory(text,text[]),public.get_fcf_target_pricing_snapshot(text),public.read_fcf_current_target_receipt(text)from public,anon,authenticated;
grant execute on function public.import_fcf_current_target(text,text),public.check_fcf_current_target(text,text,boolean),public.get_fcf_current_target_inventory(text,text[]),public.get_fcf_target_pricing_snapshot(text),public.read_fcf_current_target_receipt(text)to service_role;
